// MT2009_PLUS_TITLES_V1 (structs): Tytuly (server-patches/tytuly/README.md). CG 185: a sub-header (OPEN = the hello / refresh,
// EQUIP, UNEQUIP) and a title. GC 189 is dynamic: TPacketGCTitle, then wCount rows (TABLE: TPacketGCTitleRow, PLAYER:
// TPacketGCTitleOwned) or one record (EQUIPPED: DWORD, NOTIFY: TPacketGCTitleNotify, VISUAL: TPacketGCTitleVisual).
// The exe has the same (client-patches/exe UserInterface/Packet.h, the same static_assert).
enum
{
	TITLE_CG_OPEN = 0,
	TITLE_CG_EQUIP = 1,
	TITLE_CG_UNEQUIP = 2,
	TITLE_GC_TABLE = 0,
	TITLE_GC_PLAYER = 1,
	TITLE_GC_EQUIPPED = 2,
	TITLE_GC_NOTIFY = 3,
	TITLE_GC_VISUAL = 4,
	TITLE_NAME_LEN = 32,
	TITLE_CONDITION_LEN = 160,
	TITLE_EFFECT_LEN = 96,
};

typedef struct SPacketCGTitle
{
	BYTE	bHeader;
	BYTE	bSubHeader;
	DWORD	dwTitle;
} TPacketCGTitle;

typedef struct SPacketGCTitle
{
	BYTE	bHeader;
	WORD	wSize;
	BYTE	bSubHeader;
	WORD	wCount;
} TPacketGCTitle;

typedef struct SPacketGCTitleRow
{
	DWORD	dwTitle;
	BYTE	bType;			// 1 the name only, 3 an effect over the head, 4 the name on a plate
	BYTE	bPermanent;
	WORD	wResource;		// d:/ymir work/ui/game/title/titles/title_<wResource>.sub
	DWORD	dwDuration;		// a timed title's default time (s)
	DWORD	dwColor;		// the name's colour (ARGB)
	short	sEffectZ;		// the effect's height over the head (added to the exe's default)
	char	szName[TITLE_NAME_LEN + 1];
	char	szCondition[TITLE_CONDITION_LEN + 1];
	char	szEffect[TITLE_EFFECT_LEN + 1];
} TPacketGCTitleRow;

typedef struct SPacketGCTitleOwned
{
	DWORD	dwTitle;
	DWORD	dwEndTime;		// 0 = for good
} TPacketGCTitleOwned;

typedef struct SPacketGCTitleNotify
{
	BYTE	bMessage;
	DWORD	dwTitle;
} TPacketGCTitleNotify;

typedef struct SPacketGCTitleVisual
{
	DWORD	dwVID;
	DWORD	dwTitle;		// 0 = none
} TPacketGCTitleVisual;

static_assert(sizeof(TPacketCGTitle) == 6 && sizeof(TPacketGCTitle) == 6 && sizeof(TPacketGCTitleRow) == 309 &&
	sizeof(TPacketGCTitleOwned) == 8 && sizeof(TPacketGCTitleNotify) == 5 && sizeof(TPacketGCTitleVisual) == 8,
	"title packets (exe the same)");

